static Fsr2ShaderBlobVK fsr2_make_blob(const uint8_t *data, uint32_t size,
        const char **srvNames, const uint32_t *srvBindings, uint32_t srvCount,
        const char **uavNames, const uint32_t *uavBindings, uint32_t uavCount,
        const char **uboNames, const uint32_t *uboBindings, uint32_t uboCount) {
    Fsr2ShaderBlobVK b = {0};
    b.data = data; b.size = size;
    b.sampledImageCount = srvCount; b.boundSampledImageNames = srvNames; b.boundSampledImageBindings = srvBindings;
    b.storageImageCount = uavCount; b.boundStorageImageNames = uavNames; b.boundStorageImageBindings = uavBindings;
    b.uniformBufferCount = uboCount; b.boundUniformBufferNames = uboNames; b.boundUniformBufferBindings = uboBindings;
    return b;
}

Fsr2ShaderBlobVK fsr2GetPermutationBlobByIndexVK(FfxFsr2Pass passId, uint32_t permutationOptions) {
    (void)permutationOptions;
    switch (passId) {
    case FFX_FSR2_PASS_GENERATE_REACTIVE:
        return fsr2_make_blob(fsr2_autogen_reactive_blob, sizeof(fsr2_autogen_reactive_blob),
            fsr2_autogen_reactive_srv_names, fsr2_autogen_reactive_srv_bindings, 2,
            fsr2_autogen_reactive_uav_names, fsr2_autogen_reactive_uav_bindings, 1,
            fsr2_autogen_reactive_ubo_names, fsr2_autogen_reactive_ubo_bindings, 1);
    case FFX_FSR2_PASS_TCR_AUTOGENERATE:
        return fsr2_make_blob(fsr2_tcr_autogen_blob, sizeof(fsr2_tcr_autogen_blob),
            fsr2_tcr_autogen_srv_names, fsr2_tcr_autogen_srv_bindings, 7,
            fsr2_tcr_autogen_uav_names, fsr2_tcr_autogen_uav_bindings, 4,
            fsr2_tcr_autogen_ubo_names, fsr2_tcr_autogen_ubo_bindings, 2);
    case FFX_FSR2_PASS_ACCUMULATE:
        return fsr2_make_blob(fsr2_accumulate_blob, sizeof(fsr2_accumulate_blob),
            fsr2_accumulate_srv_names, fsr2_accumulate_srv_bindings, 8,
            fsr2_accumulate_uav_names, fsr2_accumulate_uav_bindings, 5,
            fsr2_accumulate_ubo_names, fsr2_accumulate_ubo_bindings, 1);
    case FFX_FSR2_PASS_ACCUMULATE_SHARPEN:
        return fsr2_make_blob(fsr2_accumulate_sharpen_blob, sizeof(fsr2_accumulate_sharpen_blob),
            fsr2_accumulate_sharpen_srv_names, fsr2_accumulate_sharpen_srv_bindings, 8,
            fsr2_accumulate_sharpen_uav_names, fsr2_accumulate_sharpen_uav_bindings, 4,
            fsr2_accumulate_sharpen_ubo_names, fsr2_accumulate_sharpen_ubo_bindings, 1);
    case FFX_FSR2_PASS_COMPUTE_LUMINANCE_PYRAMID:
        return fsr2_make_blob(fsr2_compute_luminance_pyramid_blob, sizeof(fsr2_compute_luminance_pyramid_blob),
            fsr2_compute_luminance_pyramid_srv_names, fsr2_compute_luminance_pyramid_srv_bindings, 1,
            fsr2_compute_luminance_pyramid_uav_names, fsr2_compute_luminance_pyramid_uav_bindings, 4,
            fsr2_compute_luminance_pyramid_ubo_names, fsr2_compute_luminance_pyramid_ubo_bindings, 2);
    case FFX_FSR2_PASS_DEPTH_CLIP:
        return fsr2_make_blob(fsr2_depth_clip_blob, sizeof(fsr2_depth_clip_blob),
            fsr2_depth_clip_srv_names, fsr2_depth_clip_srv_bindings, 9,
            fsr2_depth_clip_uav_names, fsr2_depth_clip_uav_bindings, 2,
            fsr2_depth_clip_ubo_names, fsr2_depth_clip_ubo_bindings, 1);
    case FFX_FSR2_PASS_LOCK:
        return fsr2_make_blob(fsr2_lock_blob, sizeof(fsr2_lock_blob),
            fsr2_lock_srv_names, fsr2_lock_srv_bindings, 1,
            fsr2_lock_uav_names, fsr2_lock_uav_bindings, 2,
            fsr2_lock_ubo_names, fsr2_lock_ubo_bindings, 1);
    case FFX_FSR2_PASS_RECONSTRUCT_PREVIOUS_DEPTH:
        return fsr2_make_blob(fsr2_reconstruct_previous_depth_blob, sizeof(fsr2_reconstruct_previous_depth_blob),
            fsr2_reconstruct_previous_depth_srv_names, fsr2_reconstruct_previous_depth_srv_bindings, 4,
            fsr2_reconstruct_previous_depth_uav_names, fsr2_reconstruct_previous_depth_uav_bindings, 4,
            fsr2_reconstruct_previous_depth_ubo_names, fsr2_reconstruct_previous_depth_ubo_bindings, 1);
    case FFX_FSR2_PASS_RCAS:
        return fsr2_make_blob(fsr2_rcas_blob, sizeof(fsr2_rcas_blob),
            fsr2_rcas_srv_names, fsr2_rcas_srv_bindings, 2,
            fsr2_rcas_uav_names, fsr2_rcas_uav_bindings, 1,
            fsr2_rcas_ubo_names, fsr2_rcas_ubo_bindings, 2);
    default: break;
    }
    Fsr2ShaderBlobVK empty = {0};
    return empty;
}
